  leadSource: string;
  interestArea?: string;
  status: string;
  assignedTo?: number; // FK to employees, nullable
  privacyConsentAccepted: boolean;
  created_At: string; // Capital A for At, as per DB convention
  updated_at?: string;
}

export interface LeadCaptureListResponse {
  leadCaptures: LeadCapture[];
}

// GET ALL — POST /all_leadCaptures
export async function getAllLeadCaptures(companyId: number, searchTerm: string = '', statusFilter: string = '', interestAreaFilter: string = ''): Promise<LeadCapture[]> {
  const res = await fetch(BASE_URL + "/all_leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      "leadCaptures": [{
        "companyId": companyId,
        "searchTerm": searchTerm,
        "statusFilter": statusFilter,
        "interestAreaFilter": interestAreaFilter
      }]
    }),
  });
  if (!res.ok) throw new Error(await res.text());
  const data: LeadCaptureListResponse = await res.json();
  return data.leadCaptures ?? [];
}

// CREATE — action: 1
export async function createLeadCapture(payload: Omit<LeadCapture, "leadCaptureId" | "created_At" | "updated_at">): Promise<LeadCapture> {
  const res = await fetch(BASE_URL + "/leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "leadCaptures": [{ "action": 1, ...payload }] }),
  });
